SELECT 5::information_schema.cardinal_number + 1, pg_typeof(5::information_schema.cardinal_number);
SELECT (-1)::information_schema.cardinal_number;
SELECT 'MAYBE'::text::information_schema.yes_or_no;
SELECT 'YESX'::varchar(3)::information_schema.yes_or_no, pg_typeof('NO'::information_schema.yes_or_no);
SELECT pg_typeof('abc'::information_schema.sql_identifier), pg_typeof('abc'::information_schema.character_data);
SELECT format_type('information_schema.time_stamp'::regtype, NULL);
SELECT 1::cardinal_number;
SELECT 1::information_schema.int4;
SET search_path = information_schema, public;
SELECT 1::cardinal_number, pg_typeof(1::cardinal_number);
RESET search_path;
CREATE TABLE isd_answers(n information_schema.cardinal_number, y information_schema.yes_or_no, t information_schema.sql_identifier);
INSERT INTO isd_answers VALUES (1, 'YES', 'abc');
INSERT INTO isd_answers VALUES (-1, 'YES', 'abc');
INSERT INTO isd_answers VALUES (1, 'MAYBE', 'abc');
INSERT INTO isd_answers VALUES (1, 'MAY', 'abc');
UPDATE isd_answers SET n = -5;
SELECT *, pg_typeof(n), pg_typeof(y), pg_typeof(t) FROM isd_answers;
SELECT format_type(atttypid, atttypmod) FROM pg_attribute WHERE attrelid = 'isd_answers'::regclass AND attnum > 0 ORDER BY attnum;
SELECT table_name, column_name, domain_schema, domain_name FROM information_schema.column_domain_usage WHERE table_name = 'isd_answers' ORDER BY column_name;
SELECT column_name, data_type, domain_name, udt_name FROM information_schema.columns WHERE table_name = 'isd_answers' ORDER BY ordinal_position;
SELECT pg_typeof(table_name), pg_typeof(ordinal_position), pg_typeof(is_nullable), pg_typeof(data_type) FROM information_schema.columns WHERE table_name = 'isd_answers' LIMIT 1;
SELECT domain_name, data_type, character_maximum_length, collation_name, domain_default, udt_name FROM information_schema.domains WHERE domain_schema = 'information_schema' ORDER BY domain_name;
SELECT udt_name, domain_name FROM information_schema.domain_udt_usage WHERE domain_schema = 'information_schema' ORDER BY domain_name;
SELECT constraint_name, domain_name FROM information_schema.domain_constraints WHERE domain_schema = 'information_schema' ORDER BY constraint_name;
SELECT typname, typtype, typbasetype::regtype, typtypmod, typcollation, typelem::regtype, typcategory, typdefault FROM pg_type WHERE typname IN ('cardinal_number', 'character_data', 'sql_identifier', 'time_stamp', 'yes_or_no', '_cardinal_number', '_yes_or_no') ORDER BY typname;
SELECT conname, contypid::regtype, pg_get_constraintdef(oid) FROM pg_constraint WHERE conname IN ('cardinal_number_domain_check', 'yes_or_no_check') ORDER BY conname;
DROP TABLE isd_answers;
SELECT '{1,2}'::information_schema.cardinal_number[], pg_typeof('{a}'::information_schema.sql_identifier[]);
SELECT ARRAY['YES', 'NO']::information_schema.yes_or_no[], pg_typeof(('{1}'::information_schema.cardinal_number[])[1]);
CREATE TABLE isd_arrays(a information_schema.cardinal_number[]);
INSERT INTO isd_arrays VALUES ('{3}');
SELECT a, pg_typeof(a), pg_typeof(a[1]) FROM isd_arrays;
DROP TABLE isd_arrays;
